import numpy as np
from scipy import stats

MAX_DRIVERS = 2

def design(feats):
    # Remove near-duplicates based on correlation
    corr_pairs = []
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, i], feats.x[:, j])[0,1]) >= 0.6:
                corr_pairs.append((fid1, fid2))

    # Build set of unique features to keep
    keep = set(feats.ids)
    for fid1, fid2 in corr_pairs:
        if fid1 in keep and fid2 in keep:
            # Prefer the one with higher t-statistic
            t1 = feats.x[:, feats.column(fid1)].mean() * np.sqrt(len(feats.x))
            t2 = feats.x[:, feats.column(fid2)].mean() * np.sqrt(len(feats.x))
            if abs(t1) < abs(t2):
                keep.remove(fid1)
            else:
                keep.remove(fid2)

    # Calculate effect sizes using Welch's t-test
    effects = []
    for fid in keep:
        col = feats.column(fid)
        y0 = feats.x[feats.y == 0, col]
        y1 = feats.x[feats.y == 1, col]
        t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
        effects.append((abs(t_stat), fid))

    # Sort by effect size
    effects.sort(reverse=True)
    drivers = [fid for _, fid in effects[:MAX_DRIVERS]]

    # For logistic regression, use only top 5 features
    columns = [fid for _, fid in effects[:5]]

    # Product terms between top features
    products = []
    for i, fid1 in enumerate(columns[:3]):
        for fid2 in columns[i+1:3]:
            products.append((fid1, fid2))

    # Weighted score: sum of top features with weights
    loadings = {}
    for i, (effect, fid) in enumerate(effects[:3]):
        loadings[fid] = effect / effects[0][0] if effects[0][0] != 0 else 1

    return Design(drivers=tuple(drivers), columns=tuple(columns), 
                 products=tuple(products), loadings=loadings)

